def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def sign(a):
        return 0 if a == 0 else (1 if a > 0 else -1)

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def step_away(a, b):
        return [sign(a[0] - b[0]), sign(a[1] - b[1])]

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def best_by_distance(origin, items, prefer_far=False):
        best_item = None
        best_score = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = manhattan(origin, p)
            score = -d if prefer_far else d
            if best_score is None or score < best_score:
                best_score = score
                best_item = p
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        corners = [(0, 0)]
        if grid_h:
            corners.append((0, grid_h - 1))
        if grid_w:
            corners.append((grid_w - 1, 0))
        if grid_w and grid_h:
            corners.append((grid_w - 1, grid_h - 1))
        if corners:
            target = best_by_distance(opp_p, corners, prefer_far=True)
            if target is not None:
                return step_toward(self_p, target)
        return step_away(self_p, opp_p)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
