                return step_toward(self_p, target)
        return step_away(self_p, opp_p) if manhattan(self_p, opp_p) <= 2 else [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_distance(self_p, resources)
    if target is not None:
        if env == "resource_collection":
            return step_toward(self_p, target)
